/* ── cross-section graph ───────────────────────────────────────────────── */
function buildCross() {
  const yT = rimY();
  const yMax = yT * 1.18 + 2;
  const xMax = 7.8;

  gC.add(mkLine([V(-xMax * INW, 0, 0), V(xMax * INW, 0, 0)], lnGrey));
  gC.add(mkCone(V(xMax * INW, 0, 0), V(1, 0, 0), matGreyM, 0.03, 0.09));
  gC.add(mkLine([V(0, -1.6 * INW, 0), V(0, yMax * INW, 0)], lnGrey));
  gC.add(mkCone(V(0, yMax * INW, 0), V(0, 1, 0), matGreyM, 0.03, 0.09));

  const step = yT / 3;
  for (let k = 1; k <= 3; k++) {
    const y = step * k * INW;
    gC.add(mkLine([V(-0.45 * INW, y, 0), V(0.45 * INW, y, 0)], lnGrey));
  }
  [-6, -3, 3, 6].forEach(function (x) {
    gC.add(mkLine([V(x * INW, -0.45 * INW, 0), V(x * INW, 0.45 * INW, 0)], lnGrey));
  });

  gC.add(mkLine(sampleProfile(0), lnDark));
  gC.add(mkDot(V(XA * INW, fEval(XA) * INW, 0.002), matDarkM));
  gC.add(mkDot(V(XB * INW, fEval(XB) * INW, 0.002), matDarkM));

  const pts = waterPts2D();
  if (pts) {
    const wi = waterInfo();
    const fill = new THREE.Mesh(new THREE.ShapeGeometry(new THREE.Shape(pts)), matWater);
    fill.position.z = -0.003;
    gC.add(fill);
    const yd = wi.dep * INW, xl = wi.xL * INW, xr = wi.xR * INW;
    gC.add(mkLine([V(xl, yd, 0.002), V(xr, yd, 0.002)], lnWater));
    gC.add(mkCone(V(xl, yd, 0.002), V(-1, 0, 0), matWaterM, 0.03, 0.09));
    gC.add(mkCone(V(xr, yd, 0.002), V(1, 0, 0), matWaterM, 0.03, 0.09));
    gC.add(mkDot(V(xl, yd, 0.004), matWaterM, 0.035));
    gC.add(mkDot(V(xr, yd, 0.004), matWaterM, 0.035));
  }
}

