<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ---------------- element spec (one line per element) ----------------------
 near-end parabola      -> THREE.Line x5 offset copies (thick), 81 samples of compiled y(x) at z=+L/2, #1a1a1a
 far-end parabola       -> THREE.Line x5 offset copies (EXTRA thick), same samples at z=-L/2, #1a1a1a
 bottom ruling          -> THREE.Line thick, near vertex -> far vertex, #1a1a1a
 trough wall            -> lofted BufferGeometry ribbon (2 tris / x-step), MeshBasicMaterial white DoubleSide
 front rim (x=-6)       -> THREE.Line thick, near-lip -> far-lip, #1a1a1a      (carries "3 ft")
 back rim  (x=+6)       -> THREE.Line thick, near-lip -> far-lip, #1a1a1a
 near end chord         -> THREE.Line thick across near rim, #1a1a1a
 far end chord          -> THREE.Line EXTRA thick + 2 thick ticks, #1a1a1a     (carries "12 in")
 18 in dimension        -> THREE.Line + 2 ConeGeometry heads, #333, inside near end at the vertex abscissa
 hit targets            -> open CylinderGeometry, opacity 0, on rim / far chord / dimension arrow
 water volume (opt-in)  -> ExtrudeGeometry of Shape(profile below y=d) along Z, #4da6ff a=0.35
 water surface patch    -> 2-tri BufferGeometry #2b8cbe a=0.45 + thick LineLoop #1f6fb2
 cross-section axes     -> THREE.Line #888 + cone arrowheads + tick segments
 cross-section curve    -> THREE.Line thick #1a1a1a sampled from the same compiled y(x)
 rim points             -> SphereGeometry(0.045) #1a1a1a at (-6,y(-6)) and (6,y(6))
 cross-section water    -> ShapeGeometry fill + water line + double arrow #1f6fb2
---------------------------------------------------------------------------- */

const INW = 1 / 6;                 // 1 inch -> world units (1 unit = 6 in)
const XA = -6, XB = 6, NS = 81;    // cross-section x-domain (inches) and samples
const TH = 0.008;                  // fake line thickness (world units)

let profileFn = (x) => 0.5 * x * x;
let profileSrc = '0.5*x^2';
let waterDepth = 9;                // inches
let lengthFt = 3;                  // feet
let showWater = false;             // default: empty dimensioned trough, as printed
let viewMode = '3D';

/* ── materials ─────────────────────────────────────────────────────────── */
const matWhite = new THREE.MeshBasicMaterial({ color: 0xffffff, side: THREE.DoubleSide, polygonOffset: true, polygonOffsetFactor: 2, polygonOffsetUnits: 2 });
const matWater = new THREE.MeshBasicMaterial({ color: 0x4da6ff, transparent: true, opacity: 0.35, side: THREE.DoubleSide, depthWrite: false });
const matSurf = new THREE.MeshBasicMaterial({ color: 0x2b8cbe, transparent: true, opacity: 0.45, side: THREE.DoubleSide, depthWrite: false });
const matHit = new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0, depthWrite: false });
const matDarkM = new THREE.MeshBasicMaterial({ color: 0x1a1a1a });
const matGreyM = new THREE.MeshBasicMaterial({ color: 0x888888 });
const matArrowM = new THREE.MeshBasicMaterial({ color: 0x333333 });
const matWaterM = new THREE.MeshBasicMaterial({ color: 0x1f6fb2 });
const lnDark = new THREE.LineBasicMaterial({ color: 0x1a1a1a });
const lnDim = new THREE.LineBasicMaterial({ color: 0x333333 });
const lnGrey = new THREE.LineBasicMaterial({ color: 0x888888 });
const lnWater = new THREE.LineBasicMaterial({ color: 0x1f6fb2 });

const g3 = new THREE.Group();      // 3D trough
const gC = new THREE.Group();      // cross-section graph
scene.add(g3);

/* ── helpers ───────────────────────────────────────────────────────────── */
function V(x, y, z) { return new THREE.Vector3(x, y, z); }
function mkLine(pts, mat) { return new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), mat); }
/* screen-space thickening: duplicate the polyline with small x/y offsets */
function addThick(g, pts, mat, t) {
  t = t || TH;
  const offs = [[0, 0], [t, 0], [-t, 0], [0, t], [0, -t], [t * 0.7, t * 0.7], [-t * 0.7, -t * 0.7]];
  for (let k = 0; k < offs.length; k++) {
    const o = offs[k], p = [];
    for (let i = 0; i < pts.length; i++) p.push(V(pts[i].x + o[0], pts[i].y + o[1], pts[i].z));
    g.add(mkLine(p, mat));
  }
}
function mkCone(tip, dir, mat, r, h) {
  r = r || 0.038; h = h || 0.11;
  const m = new THREE.Mesh(new THREE.ConeGeometry(r, h, 14), mat);
  const dd = dir.clone().normalize();
  m.quaternion.setFromUnitVectors(V(0, 1, 0), dd);
  m.position.copy(tip).addScaledVector(dd, -h / 2);
  return m;
}
function mkDot(p, mat, r) {
  const m = new THREE.Mesh(new THREE.SphereGeometry(r || 0.045, 14, 10), mat);
  m.position.copy(p); return m;
}
function mkHitCyl(p1, p2, r) {
  const dir = new THREE.Vector3().subVectors(p2, p1);
  const len = Math.max(dir.length(), 1e-4);
  const m = new THREE.Mesh(new THREE.CylinderGeometry(r || 0.08, r || 0.08, len, 8, 1, true), matHit);
  m.quaternion.setFromUnitVectors(V(0, 1, 0), dir.clone().normalize());
  m.position.copy(p1).addScaledVector(dir, 0.5);
  return m;
}
function clearGroup(g) {
  for (let i = g.children.length - 1; i >= 0; i--) {
    const c = g.children[i];
    g.remove(c);
    if (c.geometry && c.geometry.dispose) c.geometry.dispose();
  }
}
function fEval(x) { let v; try { v = profileFn(x); } catch (e) { v = NaN; } return Number.isFinite(v) ? v : 0; }
function rimY() { return Math.max(fEval(XA), fEval(XB), 1); }
function sampleProfile(z) {
  const p = [];
  for (let i = 0; i < NS; i++) { const x = XA + (XB - XA) * i / (NS - 1); p.push(V(x * INW, fEval(x) * INW, z)); }
  return p;
}
function vertexIdx() {
  let bi = 0, bv = Infinity;
  for (let i = 0; i < NS; i++) {
    const x = XA + (XB - XA) * i / (NS - 1), v = fEval(x);
    if (v < bv) { bv = v; bi = i; }
  }
  return bi;
}
function vertexY() {
  const i = vertexIdx();
  return fEval(XA + (XB - XA) * i / (NS - 1));
}
/* bisection on y(x)=depth, from the vertex outward — no closed form assumed */
function edgeAt(dep, xEnd) {
  let a = 0, b = xEnd;
  if (fEval(a) >= dep) return 0;
  if (fEval(b) <= dep) return b;
  for (let i = 0; i < 60; i++) { const m = (a + b) / 2; if (fEval(m) < dep) a = m; else b = m; }
  return (a + b) / 2;
}
function waterInfo() {
  const dep = Math.min(Math.max(waterDepth, 0), rimY());
  const xR = edgeAt(dep, XB), xL = edgeAt(dep, XA);
  return { dep: dep, xL: xL, xR: xR, w: xR - xL, Lin: lengthFt * 12 };
}
function waterPts2D() {
  if (!showWater) return null;
  const wi = waterInfo();
  if (!(wi.w > 1e-3) || wi.dep <= 0.02) return null;
  const n = Math.max(14, Math.round(NS * wi.w / (XB - XA)));
  const pts = [];
  for (let i = 0; i <= n; i++) {
    const x = wi.xL + wi.w * i / n;
    pts.push(new THREE.Vector2(x * INW, Math.min(fEval(x), wi.dep) * INW));
  }
  return pts;
}
function fmt(v) { return (Math.abs(v - Math.round(v)) < 0.05) ? String(Math.round(v)) : v.toFixed(1); }
function fmtL(v) { return Number.isInteger(v) ? String(v) : v.toFixed(2); }
function pretty(src) {
  return String(src).replace(/&/g, '&amp;').replace(/</g, '&lt;')
    .replace(/\*/g, '&middot;').replace(/\^(\d+(\.\d+)?)/g, '<sup>// @FIGURE_CODE_BEGIN</sup>');
}

/* ── labels (created once, repositioned every rebuild) ─────────────────── */
const L3 = {
  depth: addLabel('18 in', V(), { fontSize: '13px' }),
  length: addLabel('3 ft', V(), { fontSize: '13px' }),
  width: addLabel('12 in', V(), { fontSize: '13px' }),
  surf: addLabel('', V(), { fontSize: '11px', color: '#1f6fb2' })
};
const LC = {
  xax: addLabel('x (in)', V(), { fontSize: '11px', color: '#555' }),
  yax: addLabel('y (in)', V(), { fontSize: '11px', color: '#555' }),
  rimL: addLabel('', V(), { fontSize: '11px' }),
  rimR: addLabel('', V(), { fontSize: '11px' }),
  eq: addLabel('', V(), { fontSize: '12px' }),
  wlab: addLabel('', V(), { fontSize: '12px', color: '#1f6fb2' }),
  dlab: addLabel('', V(), { fontSize: '12px', color: '#1f6fb2' }),
  t1: addLabel('', V(), { fontSize: '10px', color: '#666' }),
  t2: addLabel('', V(), { fontSize: '10px', color: '#666' }),
  t3: addLabel('', V(), { fontSize: '10px', color: '#666' }),
  tx1: addLabel('&minus;6', V(), { fontSize: '10px', color: '#666' }),
  tx2: addLabel('6', V(), { fontSize: '10px', color: '#666' })
};
function vis(entry, on) { entry.div.style.visibility = on ? 'visible' : 'hidden'; }

/* ── 3D trough ─────────────────────────────────────────────────────────── */
function build3D() {
  const Lin = lengthFt * 12;
  const zN = (Lin / 2) * INW, zF = -(Lin / 2) * INW;
  const near = sampleProfile(zN), far = sampleProfile(zF);
  const vi = vertexIdx();

  /* lofted wall */
  const pos = [];
  for (let i = 0; i < NS - 1; i++) {
    const a = near[i], b = near[i + 1], c = far[i + 1], e = far[i];
    pos.push(a.x, a.y, a.z, b.x, b.y, b.z, c.x, c.y, c.z);
    pos.push(a.x, a.y, a.z, c.x, c.y, c.z, e.x, e.y, e.z);
  }
  const wg = new THREE.BufferGeometry();
  wg.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  wg.computeBoundingBox(); wg.computeBoundingSphere();
  const wall = new THREE.Mesh(wg, matWhite);
  g3.add(wall);
  registerInteractive(wall, {
    title: 'Ruled parabolic wall',
    tooltip: 'The channel wall: the end profile swept along the length',
    body: 'Every cross section perpendicular to the length is the same curve y(x). That is why the surface width depends only on the depth, and the surface area is simply width \u00d7 length.'
  });

  addThick(g3, near, lnDark, TH);                         // near end curve
  addThick(g3, far, lnDark, TH * 1.7);                    // far end curve (emphasised)
  addThick(g3, [near[vi], far[vi]], lnDark, TH);          // bottom ruling (vertex line)
  addThick(g3, [near[0], far[0]], lnDark, TH);            // front rim (x = -6)
  addThick(g3, [near[NS - 1], far[NS - 1]], lnDark, TH);  // back rim  (x = +6)
  addThick(g3, [near[0], near[NS - 1]], lnDark, TH);      // near chord
  addThick(g3, [far[0], far[NS - 1]], lnDark, TH * 1.7);  // far chord ("12 in")
  const tk = 0.16;
  addThick(g3, [far[0], far[0].clone().add(V(0, 0, -tk))], lnDark, TH * 1.5);
  addThick(g3, [far[NS - 1], far[NS - 1].clone().add(V(0, 0, -tk))], lnDark, TH * 1.5);

  /* 18 in double-headed dimension arrow inside the near end */
  const xv = near[vi].x, yT = rimY() * INW, yB = vertexY() * INW, zA = zN + 0.03;
  addThick(g3, [V(xv, yB + 0.05, zA), V(xv, yT - 0.05, zA)], lnDim, 0.004);
  g3.add(mkCone(V(xv, yB, zA), V(0, -1, 0), matArrowM));
  g3.add(mkCone(V(xv, yT, zA), V(0, 1, 0), matArrowM));

  /* invisible hit targets for the three printed dimensions */
  const hDepth = mkHitCyl(V(xv, yB, zA), V(xv, yT, zA), 0.09);
  g3.add(hDepth);
  registerInteractive(hDepth, {
    title: 'Depth: 18 in',
    tooltip: '18 in — rim down to the vertex',
    body: 'The vertical distance from the open rim to the lowest point of the parabola. With the vertex at the origin this says y(\u00b16) = 18.'
  });
  const hLen = mkHitCyl(near[0], far[0], 0.09);
  g3.add(hLen);
  registerInteractive(hLen, {
    title: 'Length: ' + fmtL(lengthFt) + ' ft',
    tooltip: 'Length of the channel',
    body: 'The profile is swept unchanged along this direction, so the water-surface rectangle is (width at depth d) \u00d7 L.'
  });
  const hWid = mkHitCyl(far[0], far[NS - 1], 0.09);
  g3.add(hWid);
  registerInteractive(hWid, {
    title: 'Top width: 12 in',
    tooltip: '12 in across the open top',
    body: 'The rim points are (\u22126, 18) and (6, 18). Together with the vertex at the origin these force y = 0.5x\u00b2.'
  });

  /* water volume + highlighted surface rectangle (opt-in) */
  const pts = waterPts2D();
  if (pts) {
    const wi = waterInfo();
    const shape = new THREE.Shape(pts);
    const geo = new THREE.ExtrudeGeometry(shape, { depth: Lin * INW, bevelEnabled: false, steps: 1 });
    geo.translate(0, 0, zF);
    const body = new THREE.Mesh(geo, matWater);
    body.renderOrder = 2;
    g3.add(body);
    registerInteractive(body, {
      title: 'Water in the trough',
      tooltip: 'Water body at the current depth',
      body: 'Raising or lowering the water changes the width of its top rectangle, because the bounding curve gets wider as you move up from the vertex.'
    });

    const xl = wi.xL * INW, xr = wi.xR * INW, yd = wi.dep * INW + 0.004;
    const cap = new THREE.BufferGeometry();
    cap.setAttribute('position', new THREE.Float32BufferAttribute([
      xl, yd, zF, xr, yd, zF, xr, yd, zN,
      xl, yd, zF, xr, yd, zN, xl, yd, zN], 3));
    cap.computeBoundingBox(); cap.computeBoundingSphere();
    const capMesh = new THREE.Mesh(cap, matSurf);
    capMesh.renderOrder = 3;
    g3.add(capMesh);
    const loop = [V(xl, yd, zF), V(xr, yd, zF), V(xr, yd, zN), V(xl, yd, zN), V(xl, yd, zF)];
    addThick(g3, loop, lnWater, 0.005);
  }
}

/* ── cross-section graph ───────────────────────────────────────────────── */
function buildCross() {
  const yT = rimY();
  const yMax = yT * 1.18 + 2;
  const xMax = 7.8;

  gC.add(mkLine([V(-xMax * INW, 0, 0), V(xMax * INW, 0, 0)], lnGrey));
  gC.add(mkCone(V(xMax * INW, 0, 0), V(1, 0, 0), matGreyM, 0.03, 0.09));
  gC.add(mkLine([V(0, -1.6 * INW, 0), V(0, yMax * INW, 0)], lnGrey));
  gC.add(mkCone(V(0, yMax * INW, 0), V(0, 1, 0), matGreyM, 0.03, 0.09));

  const step = yT / 3;
  for (let k = 1; k <= 3; k++) {
    const y = step * k * INW;
    gC.add(mkLine([V(-0.45 * INW, y, 0), V(0.45 * INW, y, 0)], lnGrey));
  }
  [-6, -3, 3, 6].forEach(function (x) {
    gC.add(mkLine([V(x * INW, -0.45 * INW, 0), V(x * INW, 0.45 * INW, 0)], lnGrey));
  });

  addThick(gC, sampleProfile(0.002), lnDark, TH * 1.3);
  gC.add(mkDot(V(XA * INW, fEval(XA) * INW, 0.01), matDarkM));
  gC.add(mkDot(V(XB * INW, fEval(XB) * INW, 0.01), matDarkM));

  const pts = waterPts2D();
  if (pts) {
    const wi = waterInfo();
    const fill = new THREE.Mesh(new THREE.ShapeGeometry(new THREE.Shape(pts)), matWater);
    fill.position.z = -0.01;
    gC.add(fill);
    registerInteractive(fill, {
      title: 'Water cross section',
      tooltip: 'Region under the water line',
      body: 'The water line y = d meets the curve where y(x) = d. Those two x-values, found here by bisection, give the surface width w = x\u1d63 \u2212 x\u2097.'
    });
    const yd = wi.dep * INW, xl = wi.xL * INW, xr = wi.xR * INW;
    addThick(gC, [V(xl, yd, 0.004), V(xr, yd, 0.004)], lnWater, 0.005);
    gC.add(mkCone(V(xl, yd, 0.004), V(-1, 0, 0), matWaterM, 0.03, 0.09));
    gC.add(mkCone(V(xr, yd, 0.004), V(1, 0, 0), matWaterM, 0.03, 0.09));
    gC.add(mkDot(V(xl, yd, 0.02), matWaterM, 0.035));
    gC.add(mkDot(V(xr, yd, 0.02), matWaterM, 0.035));
  }
}

/* ── labels ────────────────────────────────────────────────────────────── */
function updateLabels() {
  const on3 = (viewMode === '3D');
  const wi = waterInfo();
  const Lin = lengthFt * 12;
  const zN = (Lin / 2) * INW, zF = -(Lin / 2) * INW;
  const yT = rimY(), yB = vertexY();
  const xv = (XA + (XB - XA) * vertexIdx() / (NS - 1)) * INW;

  vis(L3.depth, on3); vis(L3.length, on3); vis(L3.width, on3);
  vis(L3.surf, on3 && showWater && wi.w > 0.05 && wi.dep > 0.05);

  /* '18 in': left of the dimension arrow, pushed below mid-height so it never
     sits on the near-end chord or on the water line */
  L3.depth.pos.set(xv, (yB + (yT - yB) * 0.42) * INW, zN + 0.05);
  L3.depth.offset = [-27, 0];
  L3.depth.div.innerHTML = fmt(yT - yB) + ' in';

  /* '3 ft': centred above the front rim running along the receding diagonal */
  L3.length.pos.set(XA * INW, fEval(XA) * INW, 0);
  L3.length.offset = [4, -13];
  L3.length.div.innerHTML = fmtL(lengthFt) + ' ft';

  /* '12 in': above the ticked far-end chord */
  L3.width.pos.set(0, ((fEval(XA) + fEval(XB)) / 2) * INW, zF);
  L3.width.offset = [0, -15];
  L3.width.div.innerHTML = fmt(XB - XA) + ' in';

  /* surface caption moved OUTSIDE the trough, above the far rim */
  L3.surf.pos.set(((wi.xL + wi.xR) / 2) * INW, ((fEval(XA) + fEval(XB)) / 2) * INW, zF);
  L3.surf.offset = [0, -34];
