  <input id="showWater" type="checkbox"> Show water (off = figure as printed)
</label>

<label>Water depth (in): <b id="valDepth">9.0</b>
  <input id="waterDepth" type="range" min="0" max="18" step="0.5" value="9">
</label>

<label>Trough length (ft): <b id="valLen">3</b>
  <input id="troughLength" type="range" min="1" max="6" step="0.25" value="3">
</label>

<label>End profile &nbsp;y(x)&nbsp; (inches, vertex at origin)
  <input id="profile" type="text" value="0.5*x^2" spellcheck="false">
</label>

<button id="btnPrinted">Reset to printed figure</button>

<div id="readout" style="font-size:11px;line-height:1.55;border-top:1px solid #dcdfe3;padding-top:6px"></div>

<div style="display:flex;gap:4px;align-items:center;border-top:1px solid #dcdfe3;padding-top:6px">
  <button id="btnPrev">&#9664;</button>
  <button id="btnNext">&#9654;</button>
  <span id="stepNum" style="font-size:11px;color:#555">guided steps</span>
</div>
